import { buildStoragePathData, getFilePrefix } from '@payloadcms/plugin-cloud-storage/utilities';
import { buildClientUploadFetchBackHeaders } from './buildClientUploadFetchBackHeaders.js';
import { buildMediaRequestHeaders } from './buildMediaRequestHeaders.js';
import { buildMediaResponseHeaders } from './buildMediaResponseHeaders.js';
import { getDownloadResponseHeaderPolicy } from './getDownloadResponseHeaderPolicy.js';
import { hasSupportedContentEncoding } from './hasSupportedContentEncoding.js';
import { mediaErrorResponse } from './mediaErrorResponse.js';
import { resolveDownloadResponseHeaders } from './resolveDownloadResponseHeaders.js';
const PRESIGNED_DOWNLOAD_URL_EXPIRES_IN_SECONDS = 300;
export const getHandler = ({ client, collection, prefix = '' })=>{
    return async (req, { doc, headers, params: { filename, operation, uploadReference } })=>{
        try {
            const prefixArgs = {
                collection,
                collectionPrefix: prefix,
                doc,
                filename,
                req,
                uploadReference
            };
            const docPrefix = await getFilePrefix(prefixArgs);
            const { storageFilePath: key } = buildStoragePathData({
                collectionPrefix: prefix,
                docPrefix,
                filename
            });
            const resolvedResponseHeaders = resolveDownloadResponseHeaders({
                collection,
                payloadResponseHeaders: headers
            });
            const responseHeaderPolicy = getDownloadResponseHeaderPolicy({
                logger: req.payload.logger,
                responseHeaders: resolvedResponseHeaders
            });
            const { data, error } = await client.POST('/api/v0/uploads/download/sign', {
                body: {
                    collectionId: collection.slug,
                    expiresIn: PRESIGNED_DOWNLOAD_URL_EXPIRES_IN_SECONDS,
                    filename: key,
                    responseHeaders: responseHeaderPolicy
                }
            });
            if (error || !data) {
                req.payload.logger.error(`Failed to get signed download URL: ${JSON.stringify(error)}`);
                return new Response('Internal Server Error', {
                    status: 500
                });
            }
            const isClientUpload = Boolean(uploadReference);
            // Lambda responses have a 6 MB limit, so redirect normal media to its signed storage URL.
            // Payload reads client uploads and transform sources itself, so they need a response body.
            if (isRunningInLambda() && !isClientUpload && operation !== 'transform') {
                return Response.redirect(data.url, 302);
            }
            const requestHeaders = buildMediaRequestHeaders(req.headers);
            let fileResponse;
            try {
                fileResponse = await fetch(data.url, {
                    credentials: 'omit',
                    headers: requestHeaders,
                    redirect: 'manual',
                    referrerPolicy: 'no-referrer',
                    signal: req.signal
                });
            } catch  {
                // Fetch errors can contain the signed URL; log only a fixed message to avoid exposing it.
                req.payload.logger.error('Failed to fetch file from storage');
                return mediaErrorResponse(500, 'Internal Server Error');
            }
            if (fileResponse.status === 416 && requestHeaders.has('Range')) {
                await cancelResponseBody(fileResponse);
                return mediaErrorResponse(416, 'Range Not Satisfiable', fileResponse.headers.get('Content-Range') ?? undefined);
            }
            if (!fileResponse.ok) {
                await cancelResponseBody(fileResponse);
                req.payload.logger.error(`Failed to fetch file from storage: ${fileResponse.status}`);
                return mediaErrorResponse(500, 'Internal Server Error');
            }
            if (!hasSupportedContentEncoding(fileResponse.headers)) {
                await cancelResponseBody(fileResponse);
                req.payload.logger.error('Unsupported Content-Encoding from storage');
                return mediaErrorResponse(502, 'Bad Gateway');
            }
            const responseHeaders = isClientUpload ? buildClientUploadFetchBackHeaders({
                filename,
                upstreamHeaders: fileResponse.headers
            }) : buildMediaResponseHeaders({
                filename,
                upstreamHeaders: fileResponse.headers
            });
            return new Response(fileResponse.body, {
                headers: responseHeaders,
                status: fileResponse.status,
                statusText: fileResponse.statusText
            });
        } catch (err) {
            req.payload.logger.error({
                err,
                msg: 'Error in staticHandler'
            });
            return new Response('Internal Server Error', {
                status: 500
            });
        }
    };
};
function isRunningInLambda() {
    return process.env.AWS_EXECUTION_ENV?.startsWith('AWS_Lambda_') === true;
}
async function cancelResponseBody(response) {
    try {
        await response.body?.cancel();
    } catch  {
    // The response will not be consumed after an error; cancellation is best-effort cleanup.
    }
}
